unsigned int cpu_id;
unsigned int numa_node;
int status;

// Retrieve the CPU and NUMA node where the thread is running.
// The third argument (tcache) is usually NULL.
status = getcpu(&cpu_id, &numa_node, NULL);

if (status == 0) {
    // cpu_id: Logical processor ID
    // numa_node: NUMA node ID
}

